"""Assemble measured passenger evidence without promoting administrative status."""
import argparse,hashlib,json,sys
from pathlib import Path
from closure_support import ROOT,save
from itinerary_build import OUT,NAMES,SOURCES
sys.path.insert(0,str(ROOT/'tools'))
import closure
def entry(prop,level,command,result,method):
    return dict(property=prop,level=level,command=command,result=result,method=method,date='2026-11-13')
def main():
    p=argparse.ArgumentParser(description=__doc__);p.add_argument('--draft',action='store_true');a=p.parse_args()
    files=['native/passenger_itinerary.h','native/passenger_itinerary.c','native/bridge/passenger_itinerary_bridge.c']
    cert=dict(component='passenger_itinerary',status='unanalyzed',proposed_status='boundary-established' if a.draft else 'migrated',
        original=[dict(identity='GAME:'+name,address='013B:'+offset,l1='c_'+name) for name,offset in zip(NAMES,['149C','1509','153B','1582','1B29','1BBE','1BD6','1C0E'])],
        native=dict(files=files,header='native/passenger_itinerary.h',functions=['itinerary_apply'],build='python verif/itinerary_build.py'),
        purpose='Passenger itinerary, appearance and departure: objective exhaustion/completion, delayed platform competition and placement, current-sentinel arrival, cached-pixel walk, lookahead departure and exact no-op. Unit-five platform-wait initializer remains L1.',
        interface=dict(inputs=['PassengerStoneSlot with existing ActorType, full finite PassengerJourney and ordinary leg index; separate persistent ActorRenderHistory.','Borrowed immutable platform geometry, mutable availability/normal actor identity, remaining/completion bytes and fade words; any scalar words including zero countdown/period/delay.'],
            outputs=['Updated slot/render/world plus ordered typed writes and explicit immediate-tail request. The bridge publishes native journal values only; copied L1 arithmetic computes diagnostic expected values and the full machine shell.','Real existing scaler call retains CoordinateScaleScratch and near return frame; all unit-five calls remain through L1.'],
            effects=['Read leg writes destination/source and their paired indices before scaled delay and phase; exhaustion decrements byte only when DEC8 sign is clear, signals completion FE with fade -2, hides then no-op tail.','Placement claims the platform immediately and explicitly seeds only current pixel coordinates, fixed position and animation; previous/erase history survives.','Animation preserves intermediate predecrement-zero/reload/cursor/sprite stores and the departure journey advance before its immediate read-leg tail.'],
            preconditions=['Serialized ordinary nonaliasing RAM/stack, immutable bounded resources and accessible native storage. Native world actor identity below sixteen; platform references in range when live. A completing native departure has a following itinerary leg, possibly the final leg. Arbitrary transfers beyond an existing terminal are outside the native composition proof.','Native frames contain live sprite words excluding FFFF; count excludes terminal. Due arrival may point at terminal, walk may reset terminal to first nonempty frame; due departure requires current live frame and accessible following terminal/live word. Inactive animation cursors may be any word.','Bridge admits DS=DGROUP, CS=GAME, aligned slot 0..15 and one of the three exact land descriptors with the checked callback set. Water/stone/unknown descriptors and malformed callbacks retain L1.','Live source/destination platform numbers must be below ten and paired with their original doubled indices. Dormant indices are not constrained or normalized.','Read bridge resolves the complete bounded remaining journey suffix using the accepted parser; valid current leg and nonwrapping resource span, no mutable actor-output overlap. The suffix base plus four times leg is the inverse projection.','Due animations borrow the registered immutable bank beginning Animation_0E20 and ending before 1020h, at most 256 live frames. Odd/out-of-window cursors, empty walk/departure or modified out-of-bank references use explicit L1 compatibility before publication.']),
        callers=['DispatchActorUpdates G:1486/1492, ascending active physical slots; level bootstrap; descriptor tails within this unit.','DeliverPassenger (unit five, L1) installs walk-to-exit. Known callers retain conservative complete register/flag observations; no liveness elimination is claimed.'],
        callees=dict(native=['actor_alias_value','scale_level_speed'],bridge=['actor_bridge_alias_project','actor_bridge_journey','ScaleLevelSpeedToThreeHalves','BeginPassengerPlatformWait (L1 unit five)','closed internal placement/departure/read/no-op tails']),
        indirect=dict(targets=['PlacePassengerOnPlatform','BeginPassengerPlatformWait','BeginPassengerDeparture','ReadPassengerJourneyLeg','IgnoreActorState'],
            classification='Known descriptor code identities checked before native execution. Typed result.next is checked against the actual tail target after all native writes have been consumed. Callback status is preserved; no no-op substitution for unit five.'),
        memory=dict(owned=['Actor phase, journey cursor, source/destination numbers and paired index writes, journey-wait alias, sprite, animation cursor/countdown, fixed coordinates.','Platform occupancy claim; remaining/completion low bytes and fade rate/level on exhaustion.'],
            borrowed=['Immutable descriptor geometry/period/vectors/callbacks and full remaining journey; platform arrival/surface; current cached pixel X; all histories imported without recalculation.'],
            renderer='Only explicit placement writes current pixel X/Y. Previous X/Y and erase sprite/overlay survive. No mode switch clearing or full-slot dump.',
            aliases='Only IT_WAIT reads journey_wait through actor_alias_value. Existing checked bridge projection poisons inactive aliases in verification builds. All other entries read none of the checked aliases; no validity-table widening or actor header change.',
            representation='The native log carries semantic field IDs, normal actor/platform indices and resource leg numbers; only the bridge encodes doubled indices, callback identities and addresses.'),
        assumptions=['One step from arbitrary admitted slot state, not only states reached from initialization. Immutable finite resource buffers and bounded platform storage.','The full general resource-size contract retains C where symbolic profiles cover only two-frame vectors and up to three journey legs. Tests and scenarios do not promote those bounds to A/B.','L0 is untouched and L0->L1 remains C/D. L1->native A/B proofs concern the real C and do not establish byte matches.'],
        eliminated=['Native C uses no registers, memory model, code addresses or dispatch; checked output journal separates semantic ownership from the retained bridge shell.','Doubled platform and actor identities derive only under the bridge paired-write admission rule; they are not discarded for malformed states, which keep L1.'],
        retained=['DEC8 sign-gated objective update, including 0->FF discarded and 128->127 accepted; completion byte FE and wrapping fade level minus two with adjacent bytes untouched.','Zero journey delay acts immediately; nonzero delay predecrements and can place in that call. Zero animation countdown/period wraps rather than acting as a positive host timer.','First available slot claims occupancy before another slot runs; no precomputed placement list.','Arrival tests current sentinel before sprite store; departure stores current sprite before next-word sentinel test and immediate journey advance/read.','Walk uses stale renderer current pixel X for its initial signed/equality comparison; after a real one-pixel wrapped move it compares SAR5 of current X. FFFF alone resets looped animation, and no overshoot clamp is introduced.','All stale fields and histories not explicitly written remain untouched. Exact no-op preserves every register, flag and RAM word.'],
        evidence=[entry('Draft pending evidence','C','python verif/itinerary_reproduce.py --fresh','Pending: final evidence and scratch host check','Actual-C, differential and scenario runner')],
        amiga=dict(classification='similar purpose with confirmed DOS differences',finding='The accepted architecture/actor-storage model supplies design meaning. No Amiga timing, field layout or itinerary equivalence is imported; DOS transitions prevail.'),
        uncertainty=['Only the supervisor promotes status; initial administrative status remains unanalyzed.','Explicit L1 fallback proves compatibility on tested malformed cases, never a native proof for those cases.'],
        dependencies={name:closure.actual_dependencies(ROOT/name) for name in files})
    if not a.draft:
        integration=json.loads((OUT/'integration.json').read_text());assert not integration['whole_status'] and not any(row['problems'] for row in integration['cases'])
        host=json.loads((OUT/'host.json').read_text());assert host['result']=='PASS' and host['check']['passed']
        scratch=ROOT/host['scratch']
        for name in files:
            if name.endswith('.c'):assert host['build']['inputs'][str(scratch/name)]==hashlib.sha256((ROOT/name).read_bytes()).hexdigest(),'stale host source'
        finite=json.loads((OUT/'evidence/enumerate_bit/result.json').read_text());assert finite['result']=='PASS'
        mutants=json.loads((OUT/'mutants.json').read_text());assert all(row['result']=='DETECTED' for row in mutants)
        negative=json.loads((OUT/'evidence/PlacePassengerOnPlatform_bit_negative/result.json').read_text());assert negative['result']=='FAIL' and any(row[0]=='itinerary_prepare.unwind.0' for row in negative['failures'])
        cert['evidence']=[entry('Complete finite scalar slices','A','python verif/itinerary_evidence.py enumerate',finite['stdout'].strip(),
            'Nine 65536-element slices: occupied/free delay, three countdowns, period, signed scaled wait, cached X, dormant animation cursor; all 256 objective bytes at seven fade boundaries. Other inputs fixed; generated 8000x8 states are C, not A.'),
            entry('Journal/register/flag bridge and composed tails','C','python verif/itinerary_integration.py --whole --local-reference',f'PASS {len(integration["cases"])} normal/poisoned routine cases','Actual bridged L1 versus independently rebuilt L0, full declared state and ordered device observations; explicit fallback audited separately.'),
            entry('Whole-game observations','D','python verif/itinerary_integration.py --whole --local-reference','PASS all seventeen scenarios','Deterministic frame/state/device/log digests against independent rebuilt L0 references.'),
            entry('Actual scratch promotion and native host','D','python verif/itinerary_host.py -> python tools/hostbuild.py; python host/check.py --variant native','PASS seventeen maintained scenarios, departure extension and 256-frame attract smoke',
                'Maintained sources copied; only scratch passenger status=migrated; actual unmodified CLI builder/checker, all accepted committed native units (including stones) plus this passenger unit linked.'),
            entry('Defect and production-unwind controls','C','python verif/itinerary_mutants.py; python verif/itinerary_evidence.py PlacePassengerOnPlatform --negative --timeout 30',
                'PASS all five defects detected; insufficient actual itinerary_prepare loop unwind fails',
                'Scratch native objective sign, completion byte, departure lookahead, cached pixel and zero delay defects; no maintained source patch.')]
        for name in NAMES:
            proof_path=OUT/'evidence'/f'{name}_bit/result.json';proof=json.loads(proof_path.read_text());assert proof['result']=='PASS',name
            for source in ['native/passenger_itinerary.c','native/bridge/passenger_itinerary_bridge.c','verif/itinerary_harness.c','verif/itinerary_build.py','verif/itinerary_evidence.py']:
                assert proof['inputs'][source]==hashlib.sha256((ROOT/source).read_bytes()).hexdigest(),'stale proof: '+name+' '+source
            cert['evidence'].append(entry(name+' actual-C one-step','B',f'python verif/itinerary_evidence.py {name} --timeout {300 if name=="WalkPassengerToExit" else 180}',
                f'PASS {proof["seconds"]:.3f}s with bounds/pointer/signed-overflow/unwind assertions',
                'Full native journal + bridge vs actual extracted L1, including actual internal tails, real scaler and L1 unit-five initializer. Arbitrary physical slot0..15, all admitted scalar/register/flag/history/occupancy words, ten platforms, paired live indices, two live frames per vector (FFFF terminator); direct Read has three legs or one for exhaustion, departure has two or three legs and includes its immediate Read/exhaustion tail. Due animation cursor FFFE/0/2 (departure FFFE/0); non-due cursor any word. Ordinary disjoint resource/RAM/stack normalization with the first land descriptor identity (its geometry/period/frame words remain arbitrary); the other two land identities are generated C coverage. No initializer reachability assumption. No-op additionally admits arbitrary incoming segments/stack/registers.'))
        departure=json.loads((OUT/'departure/result.json').read_text());assert departure['result']=='PASS' and not any(departure['audit'][8:])
        cert['evidence'].append(entry('Input-only departure witness','D','python verif/itinerary_scenario.py',f"PASS {departure['frames']} boundaries; departure init/animation {departure['audit'][5]}/{departure['audit'][6]}, zero fallback",'Extended maintained passenger input trace, no RAM patches; independent actual L0 reference and native journal comparison.'))
        cert['proposed_status_reason']='Per-entry actual-C bounded proofs, finite exhaustive domains, C/D general resource/bridge integration and actual scratch native-host promotion pass. General vector/journey sizes and malformed compatibility remain C, so propose migrated only.'
        cert['uncertainty'] += ['Early unspecialized full dispatch profiles timed out; an array-UF nested-member solver invariant error was encountered. Final maintained profiles use checked per-entry target/depth assertions and ordinary bit-flattened arrays. Failed/overlapping exploratory receipts earn no proof.','Unit-five passenger gameplay and water handlers are retained L1; this certificate does not close their state machines.']
        inputs=[ROOT/name for name in files]+SOURCES+list((ROOT/'verif').glob('itinerary*'))+[
            ROOT/'native/actors.h',ROOT/'native/actor_resources.h',ROOT/'native/coordinate_scale.h',ROOT/'native/level.h',ROOT/'native/geometry.h',
            ROOT/'native/bridge/actor_projection.h',ROOT/'c/actors.c',ROOT/'c/actors_states.c',ROOT/'c/render_primitives.c',ROOT/'c/ugh.h',ROOT/'c/ugh_sym.h',
            ROOT/'verif/closure_support.py',ROOT/'verif/windows_job.py',ROOT/'tools/closure.py',ROOT/'tools/hostbuild.py',ROOT/'host/check.py',ROOT/'metadata/verif-tools.json']
        cert['verification_input_hashing']='sha256-lf-text';cert['verification_inputs']={path.relative_to(ROOT).as_posix():hashlib.sha256(path.read_bytes().replace(b'\r\n',b'\n')).hexdigest() for path in inputs}
    save(ROOT/'metadata/closure/passenger_itinerary.json',cert)
if __name__=='__main__':main()
